    public static function validateNumericNullSubstitution(mixed $number, null|float|int $substitute): float|int
    {
        $helper = new self();
        $number = $helper->flattenValue($number);
        if ($number === null && $substitute !== null) {
            return $substitute;
        }
        if (is_numeric($number)) {
            return $helper->getNumericIdentity() + $number;
        }

        throw new Exception($helper->errorMessageFor($number));
    }

